{
  "components": {
    "delegation-metrics": {
      "name": "delegation-metrics",
      "displayName": "Delegation Metrics",
      "description": "Task delegation events, model breakdown, cost savings, and quality gate pass rates; dimension config switches between flat 2D donut and tilted 3D doughnut",
      "category": "quality",
      "version": "2.1.0",
      "implementationKey": "delegation/DelegationMetrics",
      "configSchema": {
        "type": "object",
        "properties": {
          "dimension": {
            "type": "string",
            "enum": [
              "2d",
              "3d"
            ],
            "default": "2d",
            "title": "Dimension",
            "description": "Render as a flat 2D SVG donut or a tilted 3D doughnut scene."
          },
          "showSavings": {
            "type": "boolean",
            "default": true
          },
          "showQualityGates": {
            "type": "boolean",
            "default": true
          },
          "qualityGateThreshold": {
            "type": "number",
            "minimum": 0,
            "maximum": 1,
            "default": 0.8,
            "title": "Quality gate threshold",
            "description": "Pass-rate at or above which the Quality Gate Pass Rate stat reads green. Below this, it reads warn-amber."
          }
        },
        "additionalProperties": false
      },
      "dataSources": [
        {
          "type": "projection",
          "topic": "onex.snapshot.projection.delegation.summary.v1",
          "required": true,
          "purpose": "initial_fetch"
        },
        {
          "type": "websocket",
          "topic": "onex.snapshot.projection.delegation.summary.v1",
          "required": false,
          "purpose": "live_updates"
        }
      ],
      "events": {
        "emits": [
          {
            "name": "task_type_selected",
            "schema": {
              "type": "object",
              "properties": {
                "taskType": {
                  "type": "string"
                }
              }
            }
          }
        ],
        "consumes": [
          {
            "name": "time_range_changed"
          }
        ]
      },
      "defaultSize": {
        "w": 6,
        "h": 5
      },
      "minSize": {
        "w": 4,
        "h": 3
      },
      "maxSize": {
        "w": 12,
        "h": 8
      },
      "emptyState": {
        "waits_on": [
          "onex.snapshot.projection.delegation.summary.v1"
        ],
        "message": "No delegation events",
        "hint": "Delegation events appear when tasks are delegated to agents"
      },
      "capabilities": {
        "supports_compare": false,
        "supports_export": true,
        "supports_fullscreen": true,
        "supports_time_range": false
      },
      "paletteVisibility": "visible",
      "authorityLabel": "projection-backed"
    },
    "routing-decision-table": {
      "name": "routing-decision-table",
      "displayName": "Routing Decisions",
      "description": "LLM routing decision log with agreement rates and confidence scores; renders via IDataTableAdapter (DataTableThreeJs)",
      "category": "activity",
      "version": "2.0.0",
      "implementationKey": "routing/RoutingDecisionTable",
      "configSchema": {
        "type": "object",
        "properties": {
          "pageSize": {
            "type": "number",
            "enum": [
              10,
              25,
              50,
              100
            ],
            "default": 25,
            "title": "Rows per page",
            "description": "How many decisions to render per page before pagination controls."
          }
        },
        "additionalProperties": false
      },
      "projectionSchema": {
        "type": "object",
        "description": "Row shape from onex.snapshot.projection.delegation.decisions.v1 (migration 065_create_llm_routing_decisions.sql). Ordering authority: created_at DESC (monotonic_field).",
        "required": [
          "id",
          "created_at",
          "llm_agent",
          "fuzzy_agent",
          "agreement",
          "llm_confidence",
          "fuzzy_confidence",
          "cost_usd"
        ],
        "properties": {
          "id": {
            "type": "string",
            "description": "Row UUID."
          },
          "created_at": {
            "type": "string",
            "format": "date-time",
            "description": "Decision timestamp. Ordering authority (monotonic DESC)."
          },
          "llm_agent": {
            "type": "string",
            "description": "Agent selected by the LLM router."
          },
          "fuzzy_agent": {
            "type": "string",
            "description": "Top agent from deterministic fuzzy matching."
          },
          "agreement": {
            "type": "boolean",
            "description": "True when LLM and fuzzy candidates agree."
          },
          "llm_confidence": {
            "type": "number",
            "description": "LLM confidence score (0\u20131)."
          },
          "fuzzy_confidence": {
            "type": "number",
            "description": "Fuzzy match confidence score (0\u20131)."
          },
          "cost_usd": {
            "type": "number",
            "description": "Routing cost in USD."
          },
          "provider": {
            "type": "string",
            "description": "UPSTREAM-BLOCKED: LLM provider name. Not yet emitted by omnimarket node_projection_delegation. Follow-up required."
          },
          "model": {
            "type": "string",
            "description": "UPSTREAM-BLOCKED: Model identifier used for routing. Not yet emitted by omnimarket. Follow-up required."
          },
          "reason": {
            "type": "string",
            "description": "UPSTREAM-BLOCKED: Human-readable routing rationale. Not yet emitted by omnimarket. Follow-up required."
          },
          "selection_mode": {
            "type": "string",
            "description": "UPSTREAM-BLOCKED: Routing strategy (e.g. SEMANTIC, RULE_BASED, FALLBACK). Not yet emitted by omnimarket. Follow-up required."
          },
          "fallback": {
            "type": "string",
            "description": "UPSTREAM-BLOCKED: Fallback agent or strategy used when primary routing fails. Not yet emitted by omnimarket. Follow-up required."
          }
        }
      },
      "displayContract": {
        "type": "object",
        "description": "Tabular layout rendered by IDataTableAdapter (DataTableThreeJs). Sort, paginate, and search controls present. Columns: created_at, provider, model, reason, selection_mode, fallback, llm_agent, fuzzy_agent, agreement, llm_confidence, fuzzy_confidence, cost_usd. Upstream-blocked columns (provider, model, reason, selection_mode, fallback) render headers with empty cells \u2014 no fallback literal.",
        "properties": {
          "columns": {
            "type": "array",
            "items": {
              "type": "string",
              "enum": [
                "created_at",
                "provider",
                "model",
                "reason",
                "selection_mode",
                "fallback",
                "llm_agent",
                "fuzzy_agent",
                "agreement",
                "llm_confidence",
                "fuzzy_confidence",
                "cost_usd"
              ]
            }
          },
          "controls": {
            "type": "array",
            "items": {
              "type": "string",
              "enum": [
                "sort",
                "pagination",
                "search"
              ]
            }
          }
        }
      },
      "dataSources": [
        {
          "type": "projection",
          "topic": "onex.snapshot.projection.delegation.decisions.v1",
          "required": true,
          "purpose": "initial_fetch"
        },
        {
          "type": "websocket",
          "topic": "onex.snapshot.projection.delegation.decisions.v1",
          "required": false,
          "purpose": "live_updates"
        }
      ],
      "events": {
        "emits": [
          {
            "name": "decision_selected"
          }
        ],
        "consumes": [
          {
            "name": "time_range_changed"
          }
        ]
      },
      "defaultSize": {
        "w": 12,
        "h": 6
      },
      "minSize": {
        "w": 6,
        "h": 4
      },
      "maxSize": {
        "w": 12,
        "h": 12
      },
      "emptyState": {
        "waits_on": [
          "onex.snapshot.projection.delegation.decisions.v1"
        ],
        "message": "No routing decisions",
        "hint": "Routing decisions appear when LLM routing is active"
      },
      "capabilities": {
        "supports_compare": false,
        "supports_export": true,
        "supports_fullscreen": true,
        "supports_time_range": true
      },
      "paletteVisibility": "visible",
      "authorityLabel": "projection-backed"
    },
    "usage-by-model-day": {
      "name": "usage-by-model-day",
      "displayName": "Usage by Model and Day",
      "description": "Tokens in, tokens out and measured cost per model per UTC day, with the count of calls whose cost was not measured. Every value is served by node_projection_usage_by_model_day; the widget sums nothing and shows Not measured, never 0, for a cost nobody measured.",
      "category": "cost",
      "version": "1.0.0",
      "implementationKey": "usage/UsageByModelDayWidget",
