        "type": "object",
        "required": [
          "tenant_id",
          "usage_day",
          "model_id",
          "input_tokens",
          "output_tokens",
          "call_count"
        ],
        "properties": {
          "tenant_id": {
            "type": "string",
            "description": "The reading tenant; the exposure's tenant_column, so the server scopes the read."
          },
          "usage_day": {
            "type": "string",
            "format": "date",
            "description": "UTC day of the calls."
          },
          "model_id": {
            "type": "string",
            "description": "Model the calls ran on."
          },
          "input_tokens": {
            "type": "integer",
            "description": "Tokens in, summed by the projection over every call."
          },
          "output_tokens": {
            "type": "integer",
            "description": "Tokens out, summed by the projection over every call."
          },
          "cost_usd": {
            "type": [
              "number",
              "string"
            ],
            "description": "Cost of every call, estimates included. Not rendered."
          },
          "measured_cost_usd": {
            "type": [
              "number",
              "string",
              "null"
            ],
            "description": "Cost of the calls whose cost was measured; NULL when none was."
          },
          "unmeasured_call_count": {
            "type": "integer",
            "description": "Calls whose cost was estimated or not recorded."
          },
          "call_count": {
            "type": "integer",
            "description": "Every call for the day and model."
          }
        }
      },
      "dataSources": [
        {
          "type": "projection",
          "topic": "onex.snapshot.projection.usage-by-model-day.v1",
          "required": true,
          "purpose": "initial_fetch"
        }
      ],
      "events": {
        "emits": [],
        "consumes": []
      },
      "defaultSize": {
        "w": 12,
        "h": 4
      },
      "minSize": {
        "w": 6,
        "h": 3
      },
      "maxSize": {
        "w": 12,
        "h": 10
      },
      "emptyState": {
        "waits_on": [
          "onex.snapshot.projection.usage-by-model-day.v1"
        ],
        "message": "No usage rows yet",
        "hint": "Rows appear once llm-call-completed events reach node_projection_usage_by_model_day."
      },
      "capabilities": {
        "supports_compare": false,
        "supports_export": true,
        "supports_fullscreen": true,
        "supports_time_range": false
      },
      "paletteVisibility": "visible",
      "authorityLabel": "degraded"
    },
    "usage-savings-series": {
      "name": "usage-savings-series",
      "displayName": "Savings per Day",
      "description": "Savings per UTC day against the one baseline, named in the series title, from node_projection_metering_summary's day rows. A modelled counterfactual: the runs' tokens priced at the baseline's list price. Null savings render Not measured, never 0.",
      "category": "cost",
      "version": "1.0.0",
