        "type": "object",
        "required": [
          "tenant_id",
          "window_kind",
          "window_start",
          "baseline_model"
        ],
        "properties": {
          "tenant_id": {
            "type": "string",
            "description": "The reading tenant; the exposure's tenant_column."
          },
          "window_kind": {
            "type": "string",
            "enum": [
              "day",
              "all"
            ],
            "description": "Only day rows are drawn; the all row is the Overview headline."
          },
          "window_start": {
            "type": "string",
            "description": "UTC day of a day row; empty on the all row."
          },
          "baseline_model": {
            "type": "string",
            "description": "The baseline the savings are stated against."
          },
          "baseline_state": {
            "type": "string",
            "enum": [
              "resolved",
              "unresolved"
            ]
          },
          "runs_total": {
            "type": "integer"
          },
          "savings_usd": {
            "type": [
              "number",
              "string",
              "null"
            ],
            "description": "NULL when no run of the day was measured."
