        "h": 4
      },
      "minSize": {
        "w": 4,
        "h": 3
      },
      "maxSize": {
        "w": 12,
        "h": 10
      },
      "emptyState": {
        "waits_on": [
          "onex.snapshot.projection.metering-summary.v1"
        ],
        "message": "No savings rows yet",
